@startuml
class Course {
  +id: String
  +code: String
  +credits: Integer
  +grade: String
  +gradePoint: Number
}
class CourseService {
  +list(): Course
  +create(code: String, credits: Integer, grade: String, gradePoint: Number): Course
  +update(id: String): Course
  +remove(id: String): void
}
class CourseRepository {
  +list(): Course
  +findById(id: String): Course
  +create(value: Course): Course
  +update(id: String): Course
  +remove(id: String): void
}
CourseService --> CourseRepository : uses
CourseRepository --> Course : persists
@enduml
